    font-weight: 700;
    color: #fff;
    transition: background 0.1s;
  }
  .cell[data-val="0"]  { background: #16213e; color: transparent; }
  .cell[data-val="2"]  { background: #2d4059; color: #eee; }
  .cell[data-val="4"]  { background: #3a506b; color: #eee; }
