<body>
<h1>2048</h1>
<div class="header">
  <div id="score-box">
    <div class="label">Score</div>
    <div id="score">0</div>
  </div>
  <button id="reset">New Game</button>
</div>
<div id="board"></div>
<div class="info">Use arrow keys to move tiles</div>

<script>
(function() {
  const SIZE = 4;
  let grid = [];
  let currentScore = 0;

  function makeEmptyGrid() {
    return Array.from({length: SIZE}, () => Array(SIZE).fill(0));
  }

  function emptyPositions(g) {
    const pos = [];
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (g[r][c] === 0) pos.push([r, c]);
    return pos;
  }

  function spawnTile(g) {
    const pos = emptyPositions(g);
    if (pos.length === 0) return;
    const [r, c] = pos[Math.floor(Math.random() * pos.length)];
    g[r][c] = Math.random() < 0.9 ? 2 : 4;
  }

  // Slide a single row left, returns {row, score}
  function slideRowLeft(row) {
    let arr = row.filter(x => x !== 0);
    let score = 0;
    for (let i = 0; i < arr.length - 1; i++) {
      if (arr[i] === arr[i+1]) {
        arr[i] *= 2;
        score += arr[i];
        arr.splice(i+1, 1);
      }
    }
    while (arr.length < SIZE) arr.push(0);
    return { row: arr, score };
  }

  function gridsEqual(a, b) {
    for (let r = 0; r < SIZE; r++)
      for (let c = 0; c < SIZE; c++)
        if (a[r][c] !== b[r][c]) return false;
    return true;
  }

  function applyMove(direction) {
    const oldGrid = grid.map(r => [...r]);
    let totalScore = 0;

    if (direction === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const { row, score } = slideRowLeft(grid[r]);
        grid[r] = row;
        totalScore += score;
      }
    } else if (direction === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const { row, score } = slideRowLeft([...grid[r]].reverse());
        grid[r] = row.reverse();
        totalScore += score;
      }
    } else if (direction === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = grid.map(r => r[c]);
        const { row, score } = slideRowLeft(col);
        for (let r = 0; r < SIZE; r++) grid[r][c] = row[r];
        totalScore += score;
      }
    } else if (direction === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = grid.map(r => r[c]).reverse();
        const { row, score } = slideRowLeft(col);
        const newCol = row.reverse();
        for (let r = 0; r < SIZE; r++) grid[r][c] = newCol[r];
        totalScore += score;
      }
    }

    const changed = !gridsEqual(oldGrid, grid);
    if (changed) {
      currentScore += totalScore;
      spawnTile(grid);
      render();
    }
    return changed;
  }

  function render() {
    const boardEl = document.getElementById('board');
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const val = grid[r][c];
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.setAttribute('data-val', val);
        cell.textContent = val !== 0 ? val : '';
        boardEl.appendChild(cell);
      }
    }
    document.getElementById('score').textContent = currentScore;
  }

  function newGame() {
    grid = makeEmptyGrid();
    currentScore = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  // Arrow key handler
  document.addEventListener('keydown', (e) => {
    const map = {
      ArrowLeft: 'left', ArrowRight: 'right',
      ArrowUp: 'up', ArrowDown: 'down'
    };
    if (map[e.key]) {
      e.preventDefault();
      applyMove(map[e.key]);
    }
  });

  document.getElementById('reset').addEventListener('click', newGame);

  // Public API
  window.game = {
    size: SIZE,
    reset() { newGame(); },
    move(direction) { return applyMove(direction); },
    board() { return grid.map(r => [...r]); },
    setBoard(arr) {
      for (let r = 0; r < SIZE; r++)
        for (let c = 0; c < SIZE; c++)
          grid[r][c] = arr[r][c];
      render();
    },
    score() { return currentScore; }
  };

  // Start
  newGame();
})();
</script>
</body>
</html>
